service.tests/test_pricing.py:
import unittest

from pricing import order_total


class PricingAcceptanceTests(unittest.TestCase):
    def test_percentage(self):
        self.assertEqual(order_total([(2, 10.0)], percent=10), 18.0)

    def test_zero_percentage(self):
        self.assertEqual(order_total([(1, 5.5), (3, 2.0)]), 11.5)

